import{_ as a,o as i,c as n,ak as t,bl as r,bm as o,bn as s,bo as l,bp as m}from"./chunks/framework.D598W_kV.js";const _=JSON.parse('{"title":"Créer des animation images par image (Frame-by-Frame Animation)","description":"","frontmatter":{},"headers":[],"relativePath":"16_AnimationImageParImage.md","filePath":"16_AnimationImageParImage.md","lastUpdated":1767036468000}'),p={name:"16_AnimationImageParImage.md"};function u(d,e,c,g,f,h){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="creer-des-animation-images-par-image-frame-by-frame-animation" tabindex="-1">Créer des animation images par image (Frame-by-Frame Animation) <a class="header-anchor" href="#creer-des-animation-images-par-image-frame-by-frame-animation" aria-label="Permalink to “Créer des animation images par image (Frame-by-Frame Animation)”">​</a></h1><p>Les animations images par image (frame-by-frame) sont une technique couramment utilisée dans les jeux 2D pour créer des animations fluides en affichant une séquence d&#39;images (sprites) rapidement les unes après les autres. Unity facilite la création de ce type d&#39;animation grâce à son système d&#39;animation intégré.</p><h2 id="preparation-des-images-pour-l-animation" tabindex="-1">Préparation des images pour l&#39;animation <a class="header-anchor" href="#preparation-des-images-pour-l-animation" aria-label="Permalink to “Préparation des images pour l&#39;animation”">​</a></h2><p>Avant de créer une animation images par image, assurez-vous que vous avez une série d&#39;images (sprites) prêtes à être utilisées. Chaque image doit représenter une étape différente de l&#39;animation.</p><p>Placez le pivot de chaque sprite au même endroit pour assurer une transition fluide entre les images lors de l&#39;animation.</p><h3 id="modifier-le-pivot-d-un-sprite" tabindex="-1">Modifier le pivot d&#39;un sprite <a class="header-anchor" href="#modifier-le-pivot-d-un-sprite" aria-label="Permalink to “Modifier le pivot d&#39;un sprite”">​</a></h3><ol><li>Sélectionnez le sprite dans le dossier <code>Assets</code>.</li><li>Dans l&#39;Inspector, cliquez sur le bouton <strong>Sprite Editor</strong>.</li><li>Dans le Sprite Editor, sélectionnez l&#39;outil <strong>Pivot</strong> et ajustez la position du pivot selon vos besoins (par exemple, au centre ou en bas du sprite).</li><li>Cliquez sur <strong>Apply</strong> pour enregistrer les modifications.</li></ol><h2 id="creation-de-l-animation-images-par-image" tabindex="-1">Création de l&#39;animation images par image <a class="header-anchor" href="#creation-de-l-animation-images-par-image" aria-label="Permalink to “Création de l&#39;animation images par image”">​</a></h2><ol><li>Ouvrez la fenêtre <strong>Animation</strong> en allant dans le menu <strong>Window &gt; Animation &gt; Animation</strong>.</li><li>Sélectionnez le GameObject auquel vous souhaitez ajouter l&#39;animation (par exemple, un personnage ou un objet).</li><li>Dans la fenêtre Animation, cliquez sur le bouton <strong>Create</strong> pour créer une nouvelle animation. Cela va ajouter un composant <strong>Animator</strong> au GameObject si ce n&#39;est pas déjà fait et créer un fichier d&#39;animation dans le dossier <code>Assets/animations</code>.</li><li>Enregistrez le fichier d&#39;animation avec un nom approprié au format suivant <code>objet_nomDeLanimation</code> (par exemple, &quot;perso_repos&quot;, &quot;ennemi_marche&quot;).</li></ol><p><img src="'+r+'" alt="Créer un composant animator"><img src="'+o+'" alt="Enregistrement d&#39;une animation"></p><ol start="5"><li>Faites glisser les images (sprites) de l&#39;animation depuis le dossier <code>Assets</code> vers la fenêtre Animation. Placez-les dans l&#39;ordre souhaité pour l&#39;animation.</li><li>Ajustez le framerate (images par seconde) de l&#39;animation en modifiant la valeur <strong>Samples</strong> dans la fenêtre Animation. Une valeur courante est 12 ou 24 images par seconde, selon la fluidité souhaitée. (si vous ne vous voyez pas cette option, cliquez sur les 3 petits points en haut à droite de la fenêtre Animation et sélectionnez <strong>Show Samples</strong>).</li></ol><p><img src="'+s+'" alt="Glissez les images dans la fenêtre Animation"></p><ol start="7"><li>Si vous voulez que l&#39;animation se répète en boucle, assurez-vous que l&#39;option <strong>Loop Time</strong> est cochée dans l&#39;Inspector lorsque vous sélectionnez le fichier d&#39;animation.</li></ol><p><img src="'+l+'" alt="Animation en boucle"></p><ol start="8"><li>Testez l&#39;animation en appuyant sur le bouton <strong>Play</strong> dans la fenêtre Animation.</li></ol><h3 id="deplacement-par-programmation-et-animation" tabindex="-1">Déplacement par programmation et animation <a class="header-anchor" href="#deplacement-par-programmation-et-animation" aria-label="Permalink to “Déplacement par programmation et animation”">​</a></h3><p>Si vous souhaitez déplacer un GameObject par programmation ET en utilisant aussi une animation par interpolation, vous pouvez le faire en combinant les deux approches.</p><p>Cependant, il est important de noter que les animations peuvent écraser les modifications par programmation si elles affectent les mêmes propriétés. Il n&#39;y a pas de problème avec les animations images par image, car elles ne modifient généralement pas les propriétés de position, rotation ou échelle du GameObject mais si vous animez aussi ces propriétés par interpolation en plus des images par image, cela peut poser problème.</p><p>Pour éviter cela, <strong>placez l&#39;élément animé dans un GameObject parent et appliquez les scripts de déplacement par programmation au parent.</strong></p><p><img src="'+m+'" alt="Combiner script et animation "></p><p><a href="https://learn.unity.com/tutorial/introduction-to-sprite-animations" target="_blank" rel="noreferrer">Documentation officielle Unity sur l&#39;animation de sprites 2D</a></p>',21)])])}const v=a(p,[["render",u]]);export{_ as __pageData,v as default};
